from .rd_parameters_getter import RDParametersGetter


class RDBTSUnitParameters(RDParametersGetter):
    CELLS_MANAGED_OBJECTS = {
        "lte": ["LNCEL_L", "LNCEL_R"],
        "wcdma": ["WNCEL_L", "WNCEL_R"],
        "gsm": ["GNCEL_L", "GNCEL_R"],
        "nr": ["NRCELL_L", "NRCELL_R"]
    }

    RMOD_MANAGED_OBJECTS = {
        "asirmod": ["ASIRMOD_L", "ASIRMOD_R", "RMOD_L"],
        "rmod": ["RMOD_L", "RMOD_R"]
    }

    BBMOD_MANAGED_OBJECTS = ["BBMOD_L", "BBMOD_R", "BBMOD_A"]

    SMOD_MANAGED_OBJECTS = ["SMOD_L", "SMOD_R", "SMOD_A"]

    def __init__(self):
        super(RDBTSUnitParameters, self).__init__()

    def get_parameters_for_definied_managed_objects(self, parameters, managed_objects_name, unit_type=None,
                                                    dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        r"""
        Gets given parameters for definied managed objects in class, e.g. for cells, rmods, bbmods, smods.
        :param parameters: list of parameters to get
        :param managed_objects_name: name of managed objects in class
        :param unit_type: type of managed objects, e.g. lte, wcdma, gsm, nr for cells
        :param dist_name_regex: regex to get unit id from distName
        :param bts_id: gNB id - related to Test Line configuration.
        :param du_id: DU id(Distributed Unit) - id related to Test Line configuration - gnb.dus[]
        :return: dictionary with unit id as key and dictionary with parameters as value

        e.g. output:
        parameters: ["usageState"], managed_objects_name: "CELLS_MANAGED_OBJECTS", unit_type: "lte", dist_name_regex: r"_A-(\d+)"

        {3: {'usageState': 'Active'}, 1: {'usageState': 'Active'}, 4: {'usageState': 'Active'}, 2: {'usageState': 'Active'}}
        """

        unit_type = unit_type if unit_type is None else unit_type.lower()
        managed_objects = getattr(self, managed_objects_name) if unit_type is None \
            else getattr(self, managed_objects_name)[unit_type]
        units_params = {}
        combined_units_info = self.combine_managed_objects_info(managed_objects, bts_id=bts_id, du_id=du_id,
                                                                id_regex=dist_name_regex)
        if not combined_units_info:
            return units_params

        for unit_id, unit_info in combined_units_info.items():
            units_params[unit_id] = {}
            for param in parameters:
                param_value = self.get_value_for_specific_key(unit_info["parameters"], param)
                units_params[unit_id][param] = param_value
        return units_params

    def get_parameters_for_cell_type(self, parameters, cell_type='nr', dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        return self.get_parameters_for_definied_managed_objects(parameters, "CELLS_MANAGED_OBJECTS", cell_type,
                                                                dist_name_regex=dist_name_regex, bts_id=bts_id,
                                                                du_id=du_id)

    def get_parameters_for_all_cells(self, parameters, dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        all_cells_params = {}
        for cell_type in self.CELLS_MANAGED_OBJECTS.keys():
            all_cells_params[cell_type] = self.get_parameters_for_cell_type(parameters, cell_type=cell_type,
                                                                            dist_name_regex=dist_name_regex,
                                                                            bts_id=bts_id, du_id=du_id)
        return all_cells_params

    def get_parameters_for_rmod_type(self, parameters, rmod_type='rmod', dist_name_regex=r"_A-(\d+)", bts_id=0,
                                     du_id=0):
        return self.get_parameters_for_definied_managed_objects(parameters, "RMOD_MANAGED_OBJECTS", rmod_type,
                                                                dist_name_regex=dist_name_regex, bts_id=bts_id,
                                                                du_id=du_id)

    def get_parameters_for_all_rmods(self, parameters, dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        all_rmods_params = {}
        for rmod_type in self.RMOD_MANAGED_OBJECTS.keys():
            all_rmods_params[rmod_type] = self.get_parameters_for_rmod_type(parameters, rmod_type=rmod_type,
                                                                            dist_name_regex=dist_name_regex,
                                                                            bts_id=bts_id, du_id=du_id)
        return all_rmods_params

    def get_parameters_for_bbmods(self, parameters, dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        return self.get_parameters_for_definied_managed_objects(parameters, "BBMOD_MANAGED_OBJECTS", bts_id=bts_id,
                                                                dist_name_regex=dist_name_regex, du_id=du_id)

    def get_parameters_for_smods(self, parameters, dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        return self.get_parameters_for_definied_managed_objects(parameters, "SMOD_MANAGED_OBJECTS", bts_id=bts_id,
                                                                dist_name_regex=dist_name_regex, du_id=du_id)

    def get_parameters_for_all_units(self, parameters, dist_name_regex=r"_A-(\d+)", bts_id=0, du_id=0):
        return {
            "basebandModules": self.get_parameters_for_bbmods(parameters, dist_name_regex=dist_name_regex,
                                                              bts_id=bts_id, du_id=du_id, ),
            "systemModules": self.get_parameters_for_smods(parameters, dist_name_regex=dist_name_regex,
                                                           bts_id=bts_id, du_id=du_id),
            "radioModules": self.get_parameters_for_all_rmods(parameters, dist_name_regex=dist_name_regex,
                                                              bts_id=bts_id, du_id=du_id),
            "cells": self.get_parameters_for_all_cells(parameters, dist_name_regex=dist_name_regex,
                                                       bts_id=bts_id, du_id=du_id)
        }
